package pac;
import javax.microedition.lcdui.Graphics;
/** Entry point for all offline Explore activities. */
public final class ExploreHubScreen extends Screen{
 private int sel;private static final int N=4;public ExploreHubScreen(Game g){super(g);}public void update(int dt){}
 public void key(int k){if(k==Game.K_UP||k==Game.K_LEFT)sel=(sel+N-1)%N;else if(k==Game.K_DOWN||k==Game.K_RIGHT)sel=(sel+1)%N;else if(k==Game.K_0||k==Game.K_SOFT2)game.setScreen(new MenuScreen(game));else if(k==Game.K_FIRE||k==Game.K_SOFT1){if(sel==0)game.setScreen(new WorldScreen(game));else if(sel==1)game.setScreen(new FarmScreen(game));else if(sel==2)game.setScreen(new GachaScreen(game));else game.setScreen(new CampScreen(game));}}
 public void paint(Graphics g){int W=game.W,H=game.H,fh=Art.fh;String[] n={Lang.t("KHÁM PHÁ VÀ BẮT CÓC POKÉMON","EXPLORE & CATCH"),Lang.t("FARM PET","PET FARM"),Lang.t("GACHA POKÉMON","POKÉMON GACHA"),Lang.t("BÃI POKÉMON","POKÉMON CAMP")};String[] d={Lang.t("Đi bản đồ và bắt cóc Pokémon hoang dã.","Explore maps and catch wild Pokémon."),Lang.t("Chọn pet chính, đánh và dùng skill kiếm Bóng.","Choose a lead, battle and use skills for Balls."),Lang.t("Quay Gen 1-3 theo Gen, Hệ hoặc Độ hiếm.","Draw Gen 1-3 by Gen, Type or Rarity."),Lang.t("Cử tối đa 3 pet đi treo để nhận Bóng theo giờ.","Send up to 3 pets to gather hourly Balls.")};g.setColor(0x101827);g.fillRect(0,0,W,H);Art.textBC(g,Lang.t("CHẾ ĐỘ KHÁM PHÁ","EXPLORE MODES"),W/2,5,0xFFD030);int gap=Math.max(fh*3,H/N-5),y=fh*3;for(int i=0;i<N;i++){if(i==sel){g.setColor(0x304C67);g.fillRect(5,y-3,W-10,fh*2+6);g.setColor(0x60D8FF);g.drawRect(5,y-3,W-11,fh*2+5);}Art.textB(g,n[i],10,y,i==sel?0xFFFFFF:0xAFC0D8);Art.textSmall(g,d[i],10,y+fh,W<176?0x90A0B8:0xA8B8CE);y+=gap;}Art.textSmallC(g,"FIRE: "+Lang.t("chọn","select")+"   0: "+Lang.t("về","back"),W/2,H-fh-2,0x8090B0);}
}
